function drawInsideSlide(){ctx.clearRect(0,0,1200,720);const s=slides[slide.i],t=slide.t;if(!window.Ride3D?.available&&ridePanoramaArt.complete&&ridePanoramaArt.naturalWidth){const drift=Math.sin(t*(s.type===2?13:5))*55;ctx.drawImage(ridePanoramaArt,-100+drift,-20,1400,780);}else if(!window.Ride3D?.available){ctx.fillStyle='#b5e6eb';ctx.fillRect(0,0,1200,720);}const result=window.Ride3D?.render({type:s.type,progress:t,steer:slide.steer,hero,velocity:slide.steerVelocity||0,time:motionTime,obstacles:RIDE_OBSTACLES,checked:slide.checked,lastHit:slide.lastHit,bump:slide.bump,enemies:enemies.map(e=>e.route?.i===slide.i?e.route:null)},{materials:trackMaterialArt,heroes:blockMatArt,props:ridePropsArt,villains:villainRiderArt,water:waterArt,panorama:ridePanoramaArt});if(result?.canvas){if(!result.dom)ctx.drawImage(result.canvas,0,0,1200,720);else ctx.clearRect(0,0,1200,720);}else{const art=s.type===3?tunnelRideArt:s.type===2?spiralRideArt:s.type===5?boomerangRideArt:[1,4].includes(s.type)?speedRideArt:rideArt;drawRideScenery(art,s,t,slide.steer);drawFlowingRideWater(art);drawApproachingProps(s,t);drawPlayerRider(600+slide.steer*150,625);}round(390,82,420,62,20,'#164658e8');text(s.name.toUpperCase()+' · '+names[hero].toUpperCase(),600,106,12,'#ffdfa1');text('← → / МЫШЬ · ЕДЕМ ПО ГОРКЕ',600,129,12,'#edffff');round(435,154,330,5,3,'#ffffff60');round(435,154,330*t,5,3,'#ffd984');text('Манёвры: '+(slide.score||0)+' очков',600,183,12,'#fff2c4');const behind=enemies.filter(e=>e.route?.i===slide.i&&e.route?.phase==='ride'&&e.route.t<t);if(behind.length){round(880,150,270,34,12,'#8c3e37e8');text('ГРАБИТЕЛИ ЕДУТ СЛЕДОМ',1015,172,10,'#fff1c9');}if(slide.bump)text('ПЛЮХ!',600,335,36,'#fff3c7');if(t>.92)text('БАССЕЙН ВПЕРЕДИ!',600,215,17,'#fff4c5');}
