function landWater(z){const extra=z===0?[[[125,410],[230,405],[235,475],[125,480]],[[345,405],[555,405],[560,480],[335,480]],[[650,405],[895,405],[900,480],[650,480]],[[1000,410],[1090,410],[1090,475],[1000,475]]]:z===1?[[[145,470],[285,470],[285,550],[145,550]],[[375,470],[535,470],[535,550],[375,550]],[[645,470],[805,470],[805,550],[645,550]],[[920,470],[1050,470],[1050,550],[920,550]]]:[];const pools=zones[z].slides.map(s=>{const x=s.b.x,y=s.b.y;return[[x-26,y-8],[x+34,y-8],[x+34,y+15],[x-26,y+15]];});return [...wetShapes[z],...extra,...pools];}
function buildWalkMask(z){if(walkMasks[z])return;const water=landWater(z),mask=new Uint8Array(MASK_W*MASK_H);for(let y=0;y<MASK_H;y++)for(let x=0;x<MASK_W;x++){const px=x*5+2,py=y*5+2;mask[y*MASK_W+x]=px>=45&&px<=1165&&py>=75&&py<=675&&!water.some(p=>inPoly(px,py,p))?1:0;}walkMasks[z]=mask;}
function onRoad(x,y){buildWalkMask(zone);const m=walkMasks[zone];if(!m)return true;const ix=Math.floor(x/5),iy=Math.floor(y/5);return ix>=0&&ix<MASK_W&&iy>=0&&iy<MASK_H&&!!m[iy*MASK_W+ix];}
function snapToRoad(e){if(!blocked(e.x,e.y))return;let best=null,d=Infinity;for(let y=80;y<675;y+=8)for(let x=48;x<1165;x+=8){const q=(x-e.x)**2+(y-e.y)**2;if(q<d&&!blocked(x,y)){best={x,y};d=q;}}if(best){e.x=best.x;e.y=best.y;}}
function artCell(im,col,row,cols,rows,x,y,w,h,alpha=1){if(!im.complete||!im.naturalWidth)return false;ctx.save();ctx.globalAlpha*=alpha;const cw=im.naturalWidth/cols,ch=im.naturalHeight/rows;ctx.drawImage(im,cw*col,ch*row,cw,ch,x,y,w,h);ctx.restore();return true;}
function drawTrap(t){const kinds=['foam','puddle','bucket','seal','spring'],i=kinds.indexOf(t.kind||'foam'),pulse=Math.sin(motionTime*3+t.x)*1.3,factor=parkDrawing?1/PARK_ZOOM:1,w=[89,96,88,95,87][i]*factor,h=[74,58,128,94,105][i]*factor;ctx.save();ctx.translate(t.x,t.y+pulse*factor);const arm=Math.min(1,(elapsed-(t.placedAt||0))/.35);ctx.scale(.6+.4*arm,.6+.4*arm);ctx.rotate(i===4?Math.sin(motionTime*4)*.025:0);artCell(trapArt,i,0,5,2,-w/2,-h+17*factor,w,h);ctx.restore();}
