function drawLiveMap(scene){const time=motionTime;ctx.save();waterClip(zone);const ratioX=scene.naturalWidth/1200,ratioY=scene.naturalHeight/720;ctx.globalAlpha=.48;for(let y=80;y<675;y+=5){const offset=Math.sin(y*.047+time*2.7)*3.2,sy=Math.max(0,Math.min(714,y+Math.sin(y*.029-time*1.8)*3));ctx.drawImage(scene,0,sy*ratioY,scene.naturalWidth,5*ratioY,offset,y,1200,5);}ctx.globalAlpha=1;for(let i=0;i<12;i++){const shape=wetShapes[zone][i%wetShapes[zone].length],cx=shape.reduce((v,p)=>v+p[0],0)/shape.length,cy=shape.reduce((v,p)=>v+p[1],0)/shape.length,x=cx+Math.sin(i*6.1+time*.2)*95,y=cy+Math.cos(i*9.3+time*.25)*60;waterSprite(1,time*4+i,x-45,y-25,90,50,.32);}ctx.restore();
// Light leaves sway independently of the water; no global map wobble.
for(let i=0;i<5;i++){const x=[70,1100,150,1030,700][i],y=[320,140,565,560,95][i],sx=x*ratioX,sy=y*ratioY;ctx.save();ctx.globalAlpha=.18;ctx.beginPath();ctx.ellipse(x,y,23,15,0,0,Math.PI*2);ctx.clip();ctx.drawImage(scene,sx-28*ratioX,sy-21*ratioY,56*ratioX,42*ratioY,x-28+Math.sin(time*1.3+i)*2,y-21,56,42);ctx.restore();}
}
function rideWaterClip(){ctx.beginPath();ctx.moveTo(0,720);ctx.lineTo(1200,720);ctx.lineTo(1150,575);ctx.lineTo(930,490);ctx.lineTo(740,425);ctx.lineTo(730,340);ctx.lineTo(790,268);ctx.lineTo(680,335);ctx.lineTo(615,410);ctx.lineTo(365,472);ctx.lineTo(70,565);ctx.closePath();ctx.clip();}
