function waterSprite(row,phase,x,y,w,h,alpha){if(parkDrawing){x+=w/2-w/(2*PARK_ZOOM);y+=h/2-h/(2*PARK_ZOOM);w/=PARK_ZOOM;h/=PARK_ZOOM;}const i=Math.floor(phase)%4,f=phase%1;artCell(waterArt,i,row,4,2,x,y,w,h,alpha*(1-f));artCell(waterArt,(i+1)%4,row,4,2,x,y,w,h,alpha*f);}

function drawAttraction(s){const {x,y,w,h}=s.slot,cell=s.type;if(attractionArt.complete&&attractionArt.naturalWidth){const crops={4:[10,512,420,485],5:[430,512,360,485],6:[800,512,415,485]},r=crops[cell]||[(cell%4)*384,Math.floor(cell/4)*512,384,512],sx=attractionArt.naturalWidth/1536,sy=attractionArt.naturalHeight/1024;ctx.drawImage(attractionArt,r[0]*sx,r[1]*sy,r[2]*sx,r[3]*sy,x,y,w,h);}for(let i=0;i<3;i++){const q=(motionTime*.3+i/3)%1,px=s.b.x+Math.sin(i*2)*15,py=s.b.y;waterSprite(1,motionTime*5+i,px-25,py-12,50,26,.5+q*.2);}if(s.type===0){const p=(motionTime%12)/12;if(p>.68){const f=(p-.68)/.32;waterSprite(0,motionTime*9,s.a.x-70,s.a.y-s.height+f*110,140,130,Math.sin(f*Math.PI)*.85);}}const b=stairBase(s);pixelSpace(b.x,b.y,()=>{ctx.strokeStyle='#fff1b5bf';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,5,23,10,0,0,Math.PI*2);ctx.stroke();round(-68,16,136,23,9,'#194a44ed');text('ВХОД · '+s.name,0,31,10,'#fff1bd');});}
$('#place-action').onclick=()=>{if(slide)place();else setAim(!aiming);};

function screenPoint(e){const r=canvas.getBoundingClientRect(),w=Math.min(r.width,r.height*1200/720),h=w*720/1200,ox=r.left+(r.width-w)/2,oy=r.top+(r.height-h)/2;return{x:(e.clientX-ox)/w*1200,y:(e.clientY-oy)/h*720};}
function canvasPoint(e){const p=screenPoint(e);return slide?p:{x:parkCamera.x+p.x/viewZoom,y:parkCamera.y+p.y/viewZoom};}
canvas.addEventListener('pointermove',e=>{pointerWorld=canvasPoint(e);if(slide?.phase==='ride'){slide.pointerSteer=Math.max(-.82,Math.min(.82,(pointerWorld.x-600)/320));slide.pointerAt=elapsed;}});
canvas.addEventListener('pointerleave',()=>{pointerWorld=null;if(slide)slide.pointerSteer=null;});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(state!=='playing'||slide)return;const screen=screenPoint(e);if(handleMiniMap(screen,e))return;const point=canvasPoint(e);if(point.x<0||point.x>1200||point.y<0||point.y>720)return;if(e.button===2||aiming){e.preventDefault();aimPlacement(point);return;}const ride=rideAtPoint(point);if(ride>=0){beginRide(ride);return;}snapToRoad(point);player.queuedPlacement=null;player.queuedRide=null;player.autoPath=routePath(player,point);toast('Иду к месту. Правый клик — поставить ловушку');});
const RIDE_ENTRY_RADIUS=24;
function rideAtPoint(point){return slides.findIndex(s=>{const b=s.base,r=s.slot;return Math.hypot(point.x-b.x,point.y-b.y)<36||(point.x>=r.x&&point.x<=r.x+r.w&&point.y>=r.y&&point.y<=r.y+r.h);});}
function nearestRide(){if(!player)return-1;let found=-1,d=65;slides.forEach((s,i)=>{const dist=Math.hypot(s.base.x-player.x,s.base.y-player.y);if(dist<d){found=i;d=dist;}});return found;}
function beginRide(i){if(state!=='playing'||slide||slideCooldown>0)return;aiming=false;pointerWorld=null;player.queuedPlacement=null;const b=stairBase(slides[i]);if(Math.hypot(player.x-b.x,player.y-b.y)>RIDE_ENTRY_RADIUS){player.queuedRide=i;player.autoPath=routePath(player,b);toast('Иду ко входу: '+slides[i].name);return;}player.autoPath=null;player.queuedRide=null;slide={i,t:0,phase:'climb'};toast('Поднимаемся: '+slides[i].name);beep(600);}
$('#ride-action').onclick=()=>{const i=nearestRide();if(i>=0)beginRide(i);};

const RIDE_OBSTACLES=[{at:.14,lane:-.53,kind:0},{at:.25,lane:.37,kind:1},{at:.36,lane:.04,kind:2},{at:.47,lane:.57,kind:3},{at:.58,lane:-.32,kind:1},{at:.69,lane:.40,kind:2},{at:.80,lane:-.52,kind:0},{at:.91,lane:.12,kind:3}];
function obstacleLane(i,t){const o=RIDE_OBSTACLES[i];return o.lane+Math.sin(t*11+i*2)*.07;}
function rideBend(s,t){return s.type===2?Math.sin(t*Math.PI*4)*.85:s.type===3?Math.sin(t*Math.PI*3+.2)*.65:s.type===5?Math.sin(t*Math.PI*2)*.55:[1,4].includes(s.type)?Math.sin(t*Math.PI)*.12:Math.sin(t*Math.PI*2.4)*.65;}
const artSurfaces=new WeakMap();
function artSurface(im){if(artSurfaces.has(im))return artSurfaces.get(im);const c=document.createElement('canvas');c.width=1200;c.height=720;c.getContext('2d',{alpha:false}).drawImage(im,0,0,1200,720);artSurfaces.set(im,c);return c;}
function drawRideScenery(art,s,t,steer){if(!art.complete||!art.naturalWidth)return;const bend=rideBend(s,t),look=rideBend(s,Math.min(1,t+.16)),zoom=1.20+Math.sin(t*Math.PI)*.04,w=1200*zoom,h=720*zoom;ctx.save();ctx.translate(600,360);ctx.rotate(-bend*.055);ctx.translate(-600,-360);ctx.drawImage(artSurface(art),(1200-w)/2-steer*22+(look-bend)*70,(720-h)/2+Math.sin(elapsed*1.7)*3,w,h);ctx.restore();}
function drawApproachingProps(s,t){for(let i=RIDE_OBSTACLES.length-1;i>=0;i--){const o=RIDE_OBSTACLES[i],delta=o.at-t;if(delta>.25||delta<-.07)continue;const q=1-delta/.25,k=.10+.90*q*q,center=600+(1-q)**2*160+rideBend(s,t+delta)*55*(1-q),x=center+obstacleLane(i,t)*235*k,y=230+Math.max(0,q)**1.7*430,bob=Math.sin(motionTime*4+i)*5*k,w=[80,90,78,90][o.kind]*k,h=[110,80,90,90][o.kind]*k;ctx.save();ctx.translate(x,y+bob);ctx.rotate(Math.sin(motionTime*2+i)*.08);const hit=slide.checked.includes(i)&&slide.lastHit===o.kind&&slide.bump>0;artCell(ridePropsArt,o.kind,hit?1:0,4,2,-w/2,-h,w,h);ctx.restore();waterSprite(1,motionTime*5+i,x-w*.6,y-8*k,w*1.2,30*k,.35);}}
function setClimbPose(e,s,t,dt){const a=stairTop(s),b=stairBase(s),lift=t<.43?t/.43*.48:t<.56?.48:.48+(t-.56)/.44*.52,landing=t>=.43&&t<.56;e.x=b.x+(a.x-b.x)*t+(landing?Math.sin((t-.43)/.13*Math.PI)*14:0);e.y=b.y+(a.y-b.y)*t;e.z=s.height*lift;e.moving=true;e.dir=landing?'side':'back';e.step=(e.step||0)+dt*(landing?5:9);}
function drawClimb(){const s=slides[slide.i],t=slide.phase==='platform'?1:slide.t,landing=slide.phase==='platform'||(t>.43&&t<.56),step=Math.floor(t*28),phase=motionTime*(landing?5:9);ctx.save();ctx.fillStyle='#467c8e';ctx.fillRect(0,0,1200,720);if(climbArt.complete&&climbArt.naturalWidth){const zoom=1.08+t*.035,w=1200*zoom,h=720*zoom;ctx.drawImage(climbArt,(1200-w)/2+Math.sin(phase)*1.5,(720-h)/2+t*20,w,h);}const x=600+(landing?Math.sin(t*8)*12:Math.sin(phase)*2),y=630+Math.cos(phase*2)*2;blockAvatar(hero,x,y,285,{moving:true,dir:landing?'side':'back',step:phase});round(370,85,460,75,20,'#164658e8');text('ПОДЪЁМ · '+s.name.toUpperCase(),600,112,14,'#ffdfa1');text(landing?(slide.phase==='platform'?'ПЛОЩАДКА · выходим к спуску':'ПЛОЩАДКА · следующий пролёт'):'СТУПЕНЬ '+Math.min(28,step+1)+' / 28 · W / ↑ — быстрее',600,139,12,'#ecffff');round(430,176,340,6,3,'#ffffff55');round(430,176,340*t,6,3,'#ffcf74');if(enemies.some(e=>e.route?.i===slide.i))text('ГРАБИТЕЛИ ПОДНИМАЮТСЯ СЛЕДОМ!',600,210,13,'#fff2c0');if(player.placing)text('✓ ЛОВУШКА НА ЛЕСТНИЦЕ',600,375,18,'#fff3bf');ctx.restore();}
function setAim(value){if(state!=='playing')return;aiming=value;if(player){player.queuedPlacement=null;player.autoPath=null;}toast(value?'Прицел: кликни на нужное место. Правый клик тоже ставит ловушку':'Прицел выключен');hud();}
function aimPlacement(point){if(state!=='playing'||slide)return;if(blocked(point.x,point.y)){toast('Выбери место на суше, вне бассейна');return;}const target={x:point.x,y:point.y,z:0,kind:trapKind};aiming=false;player.queuedRide=null;if(Math.hypot(point.x-player.x,point.y-player.y)>190/PARK_ZOOM){player.queuedPlacement=target;player.autoPath=routePath(player,point);toast('Подойду и поставлю '+trapTypes[trapKind].name.toLowerCase());}else place(target);hud();}
function drawAimPreview(){if(!aiming||!pointerWorld||!player||slide||state!=='playing')return;const p=pointerWorld,okay=!blocked(p.x,p.y),near=Math.hypot(p.x-player.x,p.y-player.y)<=190/PARK_ZOOM;ctx.save();ctx.strokeStyle=okay?'#ffe29ebf':'#ff7b74dd';ctx.lineWidth=2/PARK_ZOOM;ctx.setLineDash([6/PARK_ZOOM,6/PARK_ZOOM]);ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.restore();pixelSpace(p.x,p.y,()=>{ctx.strokeStyle=okay?'#ffe29e':'#ff7b74';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,4,35,16,0,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.6;drawTrap({x:0,y:0,kind:trapKind,placedAt:elapsed-1});ctx.globalAlpha=1;text(okay?(near?'КЛИК — ПОСТАВИТЬ':'ПОДОЙТИ И ПОСТАВИТЬ'):'ЗДЕСЬ ВОДА',0,-105,10,okay?'#fff0c4':'#ffb1a8');});}

function pixelSpace(x,y,draw){const previous=parkDrawing;ctx.save();ctx.translate(x,y);ctx.scale(1/viewZoom,1/viewZoom);parkDrawing=false;draw();parkDrawing=previous;ctx.restore();}
function followParkCamera(force=false){const x=Math.max(0,Math.min(1200-1200/viewZoom,(player?.x||200)-600/viewZoom)),y=Math.max(0,Math.min(720-720/viewZoom,(player?.y||160)-576/viewZoom));if(force){parkCamera.x=x;parkCamera.y=y;}else if(state!=='paused'){parkCamera.x+=(x-parkCamera.x)*.18;parkCamera.y+=(y-parkCamera.y)*.18;}}
const MINI={x:1005,y:537,w:177,h:106};
function drawMiniMap(){const m=MINI;round(m.x-7,m.y-24,m.w+14,m.h+51,13,'#153e39ed','#dbe7c75a');text('БОЛЬШОЙ ПАРК',m.x+6,m.y-8,10,'#f6e4b5','left');if(sceneImages[zone].complete)ctx.drawImage(sceneImages[zone],m.x,m.y,m.w,m.h);ctx.strokeStyle='#fff3b7';ctx.lineWidth=1.5;ctx.strokeRect(m.x+parkCamera.x/1200*m.w,m.y+parkCamera.y/720*m.h,m.w/viewZoom,m.h/viewZoom);for(const s of slides){circle(m.x+s.base.x/1200*m.w,m.y+s.base.y/720*m.h,3.5,'#ffe093');}for(const k of keys||[])if(k.zone===zone&&!k.got)circle(m.x+k.x/1200*m.w,m.y+k.y/720*m.h,3.4,'#fff3a3');if(player)circle(m.x+player.x/1200*m.w,m.y+player.y/720*m.h,4,'#f15e42');text('Нажми на карту — идти',m.x+m.w/2,m.y+m.h+17,9,'#d6e4cf');}
function handleMiniMap(p,event){const m=MINI;if(p.x<m.x||p.x>m.x+m.w||p.y<m.y||p.y>m.y+m.h)return false;let target={x:(p.x-m.x)/m.w*1200,y:(p.y-m.y)/m.h*720};const nearest=slides.findIndex(s=>Math.hypot((s.base.x-target.x)/1200*m.w,(s.base.y-target.y)/720*m.h)<10);if(nearest>=0)target={...slides[nearest].base};snapToRoad(target);if(aiming||event.button===2)aimPlacement(target);else if(nearest>=0)beginRide(nearest);else{player.queuedPlacement=null;player.queuedRide=null;player.autoPath=routePath(player,target);toast('Иду в выбранную часть парка');}return true;}

document.getElementById('zoom-in').onclick=()=>{viewZoom=Math.min(3,viewZoom+.3);followParkCamera(true);};document.getElementById('zoom-out').onclick=()=>{viewZoom=Math.max(1.8,viewZoom-.3);followParkCamera(true);};
